heroes = [
    {"name": "Aragorn", "level": 15, "weapon": "Andúril"},
    {"name": "Legolas", "level": 18, "weapon": "Longbow"},
    {"name": "Gimli", "level": 12, "weapon": "Axe"},
    {"name": "Frodo", "level": 5, "weapon": "Sting"}
]

print("By level (ascending):")
for h in sorted(heroes, key=lambda h: h["level"]):
    print(f"  {h['name']}: Level {h['level']} ({h['weapon']})")

print("\nBy name:")
for h in sorted(heroes, key=lambda h: h["name"]):
    print(f"  {h['name']}: Level {h['level']} ({h['weapon']})")

print("\nBy weapon length (descending):")
for h in sorted(heroes, key=lambda h: len(h["weapon"]), reverse=True):
    print(f"  {h['name']}: Level {h['level']} ({h['weapon']})")

heroes.reverse()
print("\nReversed:")
for h in heroes:
    print(f"  {h['name']}: Level {h['level']} ({h['weapon']})")
